window.decorateStateMap = function(svg) {
 const codes={'Alabama':'AL','Alaska':'AK','Arizona':'AZ','Arkansas':'AR','California':'CA','Colorado':'CO','Connecticut':'CT','Delaware':'DE','Florida':'FL','Georgia':'GA','Hawaii':'HI','Idaho':'ID','Illinois':'IL','Indiana':'IN','Iowa':'IA','Kansas':'KS','Kentucky':'KY','Louisiana':'LA','Maine':'ME','Maryland':'MD','Massachusetts':'MA','Michigan':'MI','Minnesota':'MN','Mississippi':'MS','Missouri':'MO','Montana':'MT','Nebraska':'NE','Nevada':'NV','New Hampshire':'NH','New Jersey':'NJ','New Mexico':'NM','New York':'NY','North Carolina':'NC','North Dakota':'ND','Ohio':'OH','Oklahoma':'OK','Oregon':'OR','Pennsylvania':'PA','Rhode Island':'RI','South Carolina':'SC','South Dakota':'SD','Tennessee':'TN','Texas':'TX','Utah':'UT','Vermont':'VT','Virginia':'VA','Washington':'WA','West Virginia':'WV','Wisconsin':'WI','Wyoming':'WY'};
 svg.setAttribute('viewBox','0 0 544 390');svg.setAttribute('preserveAspectRatio','xMidYMid meet');
 const ns='http://www.w3.org/2000/svg';
 // Small northeastern states use callouts because their land areas cannot fit a legible label.
 const offshore={'Vermont':[630,35],'New Hampshire':[650,46],'Massachusetts':[660,60],'Rhode Island':[665,74],'Connecticut':[660,88],'New Jersey':[655,102],'Delaware':[650,116],'Maryland':[645,130]};
 function landCentroid(path){
  const rings=[];let ring=[];
  for(const m of path.getAttribute('d').matchAll(/([ML])(-?[\d.]+),(-?[\d.]+)/g)){
   if(m[1]==='M'&&ring.length){rings.push(ring);ring=[]}ring.push([+m[2],+m[3]]);
  }
  if(ring.length)rings.push(ring);
  let biggest=null;
  for(const pts of rings){let area=0,cx=0,cy=0;for(let i=0;i<pts.length;i++){const [x,y]=pts[i],[nx,ny]=pts[(i+1)%pts.length],cross=x*ny-nx*y;area+=cross;cx+=(x+nx)*cross;cy+=(y+ny)*cross}if(Math.abs(area)>1e-7&&(!biggest||Math.abs(area)>Math.abs(biggest.area)))biggest={pts,area,x:cx/(3*area),y:cy/(3*area)}}
  if(!biggest){const b=path.getBBox();return [b.x+b.width/2,b.y+b.height/2]}
  const inside=(x,y)=>{let hit=false;for(let i=0,j=biggest.pts.length-1;i<biggest.pts.length;j=i++){let [xi,yi]=biggest.pts[i],[xj,yj]=biggest.pts[j];if((yi>y)!==(yj>y)&&x<(xj-xi)*(y-yi)/(yj-yi)+xi)hit=!hit}return hit};
  if(inside(biggest.x,biggest.y))return [biggest.x,biggest.y];
  // A concave state's mathematical centroid may fall in water; use the nearest interior point.
  const xs=biggest.pts.map(p=>p[0]),ys=biggest.pts.map(p=>p[1]),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);let best=null;
  for(let i=0;i<=50;i++)for(let j=0;j<=50;j++){const x=minX+(maxX-minX)*i/50,y=minY+(maxY-minY)*j/50;if(inside(x,y)){const d=(x-biggest.x)**2+(y-biggest.y)**2;if(!best||d<best.d)best={x,y,d}}}
  return best?[best.x,best.y]:[biggest.x,biggest.y];
 }
 svg.querySelectorAll('path[data-state],path.map-state').forEach(path=>{
  const name=path.dataset.state||path.getAttribute('aria-label')?.split(':')[0];if(!codes[name])return;
  let [x,y]=landCentroid(path);
  // These concave shapes need room for both letters, not just an interior center point.
  if(name==='Florida')[x,y]=[483,250];
  if(name==='Louisiana')[x,y]=[365,211];
  path.setAttribute('transform','scale(.8 1)');
  if(offshore[name]){const [ox,oy]=offshore[name];let line=document.createElementNS(ns,'line');line.setAttribute('x1',x*.8);line.setAttribute('y1',y);line.setAttribute('x2',ox*.8-4);line.setAttribute('y2',oy);line.setAttribute('class','state-leader');svg.append(line);x=ox;y=oy}
  const label=document.createElementNS(ns,'text');label.setAttribute('x',x*.8);label.setAttribute('y',y);label.setAttribute('class','state-abbr'+(path.classList.contains('never')&&!offshore[name]?' on-rust':''));label.setAttribute('data-abbr-state',name);if(offshore[name])label.setAttribute('data-offshore','true');label.setAttribute('aria-hidden','true');label.textContent=codes[name];svg.append(label);
 });
};
